#include <string>
#include <map>
#include <iostream>
#include <cmath>
#include <vector>
using namespace std;
const int N = 1005;
const int mod = 1e9 + 7;
int C[N + 5][N + 5], a[N + 5];
void add(int &a, int b) {
    a += b; if(a >= mod) a -= mod;
}
void init() {
    C[0][0] = 1;
    for(int i = 1; i <= N; i ++) {
        C[i][0] = C[i][i] = 1;
        for(int j = 1; j < i; j ++)
            C[i][j] = C[i - 1][j - 1], add(C[i][j], C[i - 1][j]);
    }
}
int main() {
    // freopen("data/10.in", "r", stdin);
    init();
    int T;
    scanf("%d", &T);
    while(T --) {
        int n, m, sum = 0;
        scanf("%d%d", &n, &m);
        for(int i = 1; i <= m; i ++)
            scanf("%d", &a[i]), sum += a[i];

        int ans = 1;
        for(int i = 1; i <= m; i ++) {
            ans = 1ll * ans * C[sum][a[i]] % mod;
            sum -= a[i];
        }
        cout << ans << endl;
    }
    return 0;
}

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <algorithm>
#include <string>
#include <map>
#include <iostream>
#include <cmath>
#include <vector>
#include <queue>
using namespace std;
const int N = 100005;
int fa[N], sz[N], dep[N], son[N], tp[N], mxId[N];
int cnt, fir[N], tar[N], nxt[N];
void link(int a, int b) {
    tar[++ cnt] = b, nxt[cnt] = fir[a], fir[a] = cnt;
}
void dfs(int x, int mxid) {
    int Mx = 0; sz[x] = 1;
    mxId[x] = max(x, mxid);
    for (int i = fir[x]; i; i = nxt[i]) {
        dep[tar[i]] = dep[x] + 1;
        dfs(tar[i], mxId[x]);
        sz[x] += sz[tar[i]];
        if (Mx < sz[tar[i]])
            Mx = sz[son[x] = tar[i]];
    }
}
void gettp(int x) {
    tp[x] = x;
    if (son[fa[x]] == x)
        tp[x] = tp[fa[x]];
    for (int i = fir[x]; i; i = nxt[i])
        gettp(tar[i]);
}
int lca(int x,int y){
    while (tp[x] != tp[y])
        dep[tp[x]] > dep[tp[y]] ? x = fa[tp[x]] : y = fa[tp[y]];
    return dep[x] < dep[y] ? x : y;
}

int main() {
    int n;
    scanf("%d", &n);
    for(int i = 2; i <= n; i ++)
        scanf("%d", &fa[i]), link(++ fa[i], i);
    dfs(1, 1), gettp(1);

    int q;
    scanf("%d", &q);
    while(q --) {
        int m, x, y;
        scanf("%d%d", &m, &x), x ++;
        for(int i = 2; i <= m; i ++)
            scanf("%d", &y), x = lca(x, ++ y);
        cout << mxId[x] - 1 << endl;
    }
    return 0;
}
